exercise.solution:
macro_rules! map_lit {
    ($($k:expr => $v:expr),* $(,)?) => {{
        let mut m = std::collections::HashMap::new();
        $(m.insert(String::from($k), $v);)*
        m
    }};
}

fn main() {
    let m = map_lit!{"a" => 1, "b" => 2};
    for (k, v) in &m {
        println!("{k}={v}");
    }
}
